'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='sasi-practice-v1';let db=[],guide=[],progress={},session=null,track='All problems',view='practice',difficulty='All',kind='All',lab='All',search='',tab='problem',guideIndex=0,interviewTrack='All problems',interviewMinutes=15;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'{}');progress=saved.progress||{};session=saved.session||null;}catch{}
const tracks=['All problems','Digital PD','Analog PD','RTL','Verification'];
const button=(text,action,value='',cls='')=>`<button class="${cls}" data-action="${action}" data-value="${esc(value)}">${text}</button>`;
function toast(s){const el=$('#toast');el.textContent=s;el.style.display='block';clearTimeout(toast.id);toast.id=setTimeout(()=>el.style.display='none',3000);}
function save(){try{localStorage.setItem(KEY,JSON.stringify({version:1,progress,session}));}catch{toast('Storage unavailable. Export your progress before leaving.');}}
function entry(id){return progress[id]||(progress[id]={notes:'',checks:[],status:'new',numeric:''});}
function done(p){return progress[p.id]?.status==='done';}
function count(t){return db.filter(p=>t==='All problems'||p.track===t).length;}
function shell(content){let completed=db.filter(done).length;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="chip" aria-hidden="true">▦</span><div>ASIC Practice<small>STONE ARCH SILICON</small></div></div><div class="navlabel">Practice tracks</div><nav class="nav" aria-label="Practice tracks">${tracks.map(t=>button(`${esc(t)}<small>${count(t)}</small>`,'track',t,view==='practice'&&track===t?'active':'')).join('')}</nav><div class="navlabel">Workbench</div><nav class="nav secondary" aria-label="Resources">${button('Lab & command guide','view','guide',view==='guide'?'active':'')}${button('Interview mode <small>↗</small>','view','interview',view==='interview'?'active':'')}${button('Study path','view','path',view==='path'?'active':'')}${button('Sources & tool map','view','sources',view==='sources'?'active':'')}</nav><div class="sidebottom"><b>${completed} / ${db.length} self-reviewed</b><div class="progressbar"><i style="width:${db.length?completed/db.length*100:0}%"></i></div>Progress is saved in this browser.<br>Personal progress · no leaderboard.${button('Export progress','export')}<label class="importlabel">Import<input type="file" id="import-progress" accept="application/json" hidden></label></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">SASi <span aria-hidden="true">/</span> <strong>${esc(view==='practice'?track:view==='guide'?'Lab & command guide':view==='interview'?'Interview mode':view==='path'?'Study path':'Sources & tool map')}</strong></div><span class="tag">EE 5327 · Labs 3–7 + beyond</span></header><div class="content">${content}</div></main></div>`;updateTimer();window.scrollTo(0,0);}
function filtered(){return db.filter(p=>(track==='All problems'||p.track===track)&&(difficulty==='All'||p.level===difficulty)&&(kind==='All'||p.kind===kind)&&(lab==='All'||(lab==='Labs 3–7'?/^Lab [3-7]/.test(p.lab):p.lab===lab))&&[p.title,p.prompt,p.track,p.lab,p.kind,p.id].join(' ').toLowerCase().includes(search.toLowerCase()));}
function chips(values,action,active){return `<div class="chips">${values.map(v=>button(esc(v),action,v,v===active?'active':'')).join('')}</div>`;}
function listRows(){const list=filtered();return list.length?list.map(p=>`<tr><td class="hide-mobile"><span class="status-dot ${done(p)?'done':''}" aria-label="${done(p)?'Self-reviewed':progress[p.id]?.notes?'Attempted':'Not started'}">${done(p)?'✓':progress[p.id]?.notes?'◐':'○'}</span></td><td class="titlecol">${button(`${esc(p.title)}<small>${esc(p.id)} · ${esc(p.track)} · ${esc(p.lab)}</small>`,'problem',p.id,'problem-link')}</td><td><span class="level ${p.level}">${p.level}</span></td><td class="hide-mobile">${esc(p.kind)}</td><td class="hide-md">${p.minutes} min</td><td>${button('→','problem',p.id,'ghost')}</td></tr>`).join(''):`<tr><td colspan="6" class="empty">No matching problems. Try another filter.</td></tr>`;}
function list(){view='practice';const tc=db.filter(p=>track==='All problems'||p.track===track), n=tc.filter(done).length;shell(`<div class="heading"><div><div class="eyebrow">The silicon workbench</div><h1>${track==='All problems'?'Practice. Debug. Defend.':esc(track)}</h1><p class="lead">${track==='Analog PD'?'Matching, parasitics, reliability, and layout decisions. Explain what you would change—and how you would verify it.':track==='Digital PD'?'Read the reports. Find the real bottleneck. Make a change you can defend.':track==='RTL'?'Design to a specification. Handle the corner cases. Explain the hardware your code creates.':track==='Verification'?'Build evidence that the design works. Challenge the checker, the stimulus, and the coverage.':'Short problems for the questions after “walk me through your design.” Start with a lab, then go deeper.'}</p></div>${button('Start interview ↗','view','interview','primary')}</div><div class="stats"><div class="stat"><b>${tc.length}</b><span>practice problems</span></div><div class="stat"><b>${n}</b><span>self-reviewed</span></div><div class="stat"><b>${tc.filter(p=>p.kind==='Report').length}</b><span>report investigations</span></div></div><div class="toolbar"><input id="search" class="search" type="search" placeholder="Search problems, commands, or topics…" aria-label="Search problems" value="${esc(search)}">${chips(['All','Easy','Medium','Hard'],'difficulty',difficulty)}</div><div class="filters"><div class="filterline"><span>TYPE</span>${chips(['All','Report','Code','Debug','Design'],'kind',kind)}</div><div class="filterline"><span>SCOPE</span>${chips(['All','Foundations','Labs 3–7','Beyond Lab 7'],'lab',lab)}</div></div><div class="tablewrap"><table><thead><tr><th class="hide-mobile" style="width:40px"></th><th>Problem</th><th>Difficulty</th><th class="hide-mobile">Format</th><th class="hide-md">Time</th><th style="width:45px"></th></tr></thead><tbody id="rows">${listRows()}</tbody></table></div><div class="footerline micro"><span id="result-count">${filtered().length} problems · All report fixtures are educational examples.</span><span>Reference solutions + interview follow-ups included</span></div>`);}
let activeId=null;
function sourcesHTML(sources){return `<ul class="source-list">${(sources||[]).map(s=>`<li>${typeof s==='string'?esc(s):`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)}</a>`}</li>`).join('')}</ul>`;}
function problem(id,changeTab=false){const p=db.find(p=>p.id===id);if(!p)return list();activeId=id;view=session?.id===id&&!session.finished?'interview':'practice';if(changeTab)tab='problem';const e=entry(id), live=session?.id===id&&!session.finished;
let left=tab==='problem'?`<p class="prompt">${esc(p.prompt)}</p>${p.artifact?`<div class="copyrow"><span>${p.kind==='Code'?'Exercise / starting point':'Educational fixture'}</span>${button('Download','fixture',id)}</div><pre class="code">${esc(p.artifact)}</pre>`:''}${!live?`<details class="hint"><summary>Need a hint?</summary><p>${esc(p.hint)}</p></details>`:''}`:tab==='theory'?`<h3>Know before you explain</h3><ul class="bullets">${p.theory.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Reading trail</h3>${sourcesHTML(p.sources)}${p.sourceNote?`<p class="micro sourcesnote">${esc(p.sourceNote)}</p>`:''}`:`<h3>Reference approach</h3><ul class="bullets">${p.solution.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${p.solutionCode?`<div class="copyrow"><span>Reference implementation</span>${button('Copy','copySolution',id)}</div><pre class="code">${esc(p.solutionCode)}</pre>`:''}<div class="reviewnote">Use this to compare your reasoning. Code and design answers are self-reviewed; this page does not execute EDA tools.</div><h3>Now defend it</h3><ol class="bullets">${p.followups.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${sourcesHTML(p.sources)}`;
shell(`${button('← Back to problems','back','','back')}<div class="heading"><div><div class="eyebrow">${esc(p.id)} / ${esc(p.track)}</div><h1>${esc(p.title)}</h1><div class="problemmeta"><span class="level ${p.level}">${p.level}</span><span class="tag">${esc(p.kind)}</span><span class="tag">${esc(p.lab)}</span><span class="micro">${p.minutes} min suggested</span></div></div></div>${live?`<div class="interviewbanner"><div><b>Think aloud. State your assumptions.</b><div class="micro">Explain the constraint, tradeoff, and evidence. Solutions unlock when you finish.</div></div><div class="timer" id="timer"></div>${button('Finish & review','finish','','primary')}</div>`:''}<div class="workspace"><section class="panel"><div class="tabs" role="tablist" aria-label="Problem content">${button('Problem','tab','problem',tab==='problem'?'active':'')}${!live?button('Theory','tab','theory',tab==='theory'?'active':'')+button('Solution','tab','solution',tab==='solution'?'active':''):''}</div><div class="panelbody">${left}${live?`<div class="interview-actions">${button('Ask a follow-up','followup')}</div><div id="followups">${(p.followups||[]).slice(0,session.followups||0).map(x=>`<p class="reviewnote">${esc(x)}</p>`).join('')}</div>`:''}</div></section><section class="panel"><div class="answerhead">Your approach <span id="save-status">Saved in this browser</span></div><label class="micro" for="answer" style="display:block;padding:14px 20px 0">${p.kind==='Code'?'Write your code, assumptions, and test cases.':'State the cause, propose a change, and explain how you will verify it.'}</label><textarea id="answer" class="editor" spellcheck="false" data-id="${id}" placeholder="${esc(p.starter||'1. What the evidence says\n2. My proposed change\n3. Tradeoff / risk\n4. How I would verify it')}">${esc(e.notes)}</textarea><div class="answeractions">${p.numeric&&!live?`<label for="numeric-answer" class="micro">${esc(p.numeric.label)}</label><div class="numeric"><input id="numeric-answer" type="number" step="any" value="${esc(e.numeric)}" placeholder="Your result"><span>${esc(p.numeric.unit||'')}</span>${button('Check value','checkNumeric',id)}</div><div id="numeric-feedback" class="feedback" aria-live="polite"></div><p class="micro">Checks this value only; it does not grade your explanation.</p>`:''}${!live?`<h3 style="margin-top:22px">Review checklist</h3><ul class="rubric">${p.rubric.map((r,i)=>`<li><label><input type="checkbox" data-rubric="${i}" data-id="${id}" ${e.checks.includes(i)?'checked':''}>${esc(r)}</label></li>`).join('')}</ul><div class="score" id="score">${e.checks.length} / ${p.rubric.length} review points</div><div class="splitrow">${button(done(p)?'✓ Self-reviewed':'Mark self-reviewed','done',id,'primary')}${button('Next problem →','next',id)}</div>`:`<p class="micro">This is a practice timer, not an automated interview evaluator. Your notes are saved as you type.</p>`}</div></section></div>`);window.scrollTo(0,0);}
function renderGuide(){view='guide';const g=guide[guideIndex];if(!g)return;shell(`<div class="heading"><div><div class="eyebrow">Command → purpose → evidence</div><h1>Lab & command guide</h1><p class="lead">Small reference cards. Learn what each command changes, then check the result. Lab-specific syntax is separated from the broader Cadence / Synopsys workflow.</p></div></div><div class="guidelayout"><nav class="guidenav" aria-label="Guide topics">${guide.map((x,i)=>button(esc(x.title),'guideTopic',i,guideIndex===i?'active':'')).join('')}</nav><section class="panel"><div class="panelbody"><span class="tag">${esc(g.scope)}</span><h2 style="margin-top:18px">${esc(g.title)}</h2><p class="micro">${esc(g.intro)}</p>${g.steps?`<div class="steps">${g.steps.map(s=>`<span>${esc(s)}</span>`).join('')}</div>`:''}${g.cards.map(c=>`<article class="commandcard"><h3>${esc(c.title)}</h3>${c.code?`<div class="copyrow"><span>${esc(c.shell||'')}</span>${button('Copy','copyCommand',`${guideIndex}:${g.cards.indexOf(c)}`)}</div><pre class="code">${esc(c.code)}</pre>`:''}<div class="commandmeaning"><span>Purpose</span><div>${esc(c.meaning)}</div><span>Check</span><div>${esc(c.check)}</div><span>Interview</span><div>${esc(c.ask)}</div></div>${c.note?`<p class="reviewnote">${esc(c.note)}</p>`:''}</article>`).join('')}<h3>Sources / scope</h3>${sourcesHTML(g.sources)}</div></section></div>`);}
const toolsMap=[['Simulation / debug','VCS / Verdi','Xcelium / SimVision'],['RTL synthesis','Design Compiler','Genus'],['Digital place & route','IC Compiler II / Fusion Compiler','Innovus'],['Timing signoff','PrimeTime','Tempus'],['Parasitic extraction','StarRC','Quantus'],['Custom schematic / layout','Custom Compiler','Virtuoso'],['Transistor simulation','PrimeSim / HSPICE','Spectre'],['Physical verification','IC Validator','Pegasus / PVS'],['Power / rail analysis','Power Compiler / PrimePower; RedHawk-SC for power integrity','Joules / Voltus'],['Formal verification','VC Formal / Formality','Jasper / Conformal']];
function renderSources(){view='sources';const links=new Map();for(const p of [...db,...guide])for(const s of p.sources||[])if(typeof s==='object')links.set(s.url,s.label);shell(`<div class="heading"><div><div class="eyebrow">Two ecosystems. Shared engineering questions.</div><h1>Sources & tool map</h1><p class="lead">Tools below have related roles, not identical commands or interchangeable databases. Use the documentation for your installed version and your lab’s licensed flow.</p></div></div><div class="panel"><table class="tooltable"><thead><tr><th>Job</th><th>Synopsys</th><th>Cadence</th></tr></thead><tbody>${toolsMap.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="studyplan"><section class="plan-card"><h2>What the labs establish</h2><p>Lab 3: synthesis and timing budgets.<br>Lab 4: optimization directives.<br>Lab 5: FSM encoding experiments.<br>Lab 6: scan design and ATPG.<br>Lab 7: switching activity, multi-Vt, clock gating.</p><p>Labs 3–7 were supplied for this build. The VCS foundation cards use the club organizer’s notes; Labs 1–2 were not supplied. Digital place-and-route, analog layout, and advanced verification are additional original practice.</p></section><section class="plan-card"><h2>How to use these sources</h2><p><a href="downloads/ASIC_leet_source.zip" download>Download the GitHub-ready source</a></p><p>Public vendor pages establish tool roles and concepts. Detailed command manuals often require university or vendor access. Use local <code>help</code>/<code>man</code> or the tool Help menu for your release.</p><p>Fixtures are synthetic and teaching answers are original. No foundry PDK, licensed standard-cell models, or proprietary vendor manuals are bundled. No simulator or synthesis engine runs in this site.</p></section></div><section class="plan-card" style="margin-top:20px"><h2>Official reading trail</h2>${sourcesHTML([...links].map(([url,label])=>({url,label})))}</section>`);}
function renderPath(){view='path';const plans=[['01','Bring up the tools','Foundations','Explain compile, elaborate, and simulate. Debug one failed run before moving on.'],['02','Constrain and synthesize','Lab 3','Calculate a timing budget. Explain the target library, link library, and what area means.'],['03','Compare real alternatives','Lab 4','Hold constraints constant and compare optimization strategies using timing and area evidence.'],['04','Architecture changes PPA','Lab 5','Compare binary and one-hot FSMs. Explain the logic depth, clock load, and verification cost.'],['05','Make the chip testable','Lab 6','Distinguish functional verification from manufacturing test. Diagnose a coverage report.'],['06','Measure power honestly','Lab 7','Use the same activity and period for power comparisons. Discuss gating overhead and multi-Vt.'],['07','Close the physical loop','Beyond Lab 7','Explore floorplan, clock trees, routing, parasitics, mismatch, and multi-corner closure.']];shell(`<div class="eyebrow">A path from commands to judgment</div><h1>Build your interview evidence.</h1><p class="lead">For each stage: solve a problem, explain it aloud, then answer the follow-ups without looking. Move on when you can justify a tradeoff with a report or a test.</p><div class="studyplan">${plans.map(([n,title,l,desc])=>`<article class="plan-card"><div class="eyebrow">${n} / ${esc(l)}</div><h2 style="margin-top:12px">${title}</h2><p>${desc}</p>${button('Open practice →','scope',l)}</article>`).join('')}<article class="plan-card"><div class="eyebrow">08 / Put it together</div><h2 style="margin-top:12px">Take the follow-up.</h2><p>Spend 15 minutes on an unfamiliar problem. Discuss requirements, alternatives, evidence, and one limitation of your approach.</p>${button('Start interview ↗','view','interview','primary')}</article></div>`);}
function interview(){view='interview';shell(`<div class="panel session-card"><div class="panelbody"><div class="eyebrow">No hints. One problem. Real reasoning.</div><h1>Take the follow-up.</h1><p class="lead">Practice answering out loud while you work. The timer keeps you focused; follow-up prompts test how well you can defend your answer.</p><h3 style="margin-top:30px">Choose a track</h3>${chips(tracks,'interviewTrack',interviewTrack)}<h3 style="margin-top:25px">Time box</h3>${chips(['10','15','25'],'interviewMinutes',String(interviewMinutes))}<div class="reviewnote">Interview mode hides theory and solutions until you finish. Review afterward using the problem’s checklist. No AI grading or recording.</div><div class="splitrow">${button('Start practice interview →','startSession','','primary')}${session&&!session.finished?button('Resume current session','resume'):''}</div></div></div>`);}
function startSession(){let pool=db.filter(p=>interviewTrack==='All problems'||p.track===interviewTrack);let fresh=pool.filter(p=>!done(p));if(fresh.length)pool=fresh;const p=pool[Math.floor(Math.random()*pool.length)];session={id:p.id,end:Date.now()+interviewMinutes*60000,followups:0,finished:false};save();tab='problem';location.hash=`problem/${p.id}`;problem(p.id);}
function updateTimer(){const e=$('#timer');if(!e||!session)return;const s=Math.max(0,Math.ceil((session.end-Date.now())/1000));e.textContent=s?`${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`:'Time to wrap up';e.classList.toggle('expired',s===0);}
setInterval(updateTimer,1000);
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied.');}catch{toast('Clipboard unavailable. Select and copy the code directly.');}}
function route(){const [r,id]=location.hash.slice(1).split('/');if(r==='problem'&&db.some(p=>p.id===id)){problem(id,true);return;}if(r==='guide'){renderGuide();return;}if(r==='interview'){interview();return;}if(r==='sources'){renderSources();return;}if(r==='path'){renderPath();return;}list();}
function navigate(hash){if(location.hash===`#${hash}`)route();else location.hash=hash;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,v=b.dataset.value,p=db.find(p=>p.id===activeId);switch(a){case'track':track=v;difficulty=kind=lab='All';search='';navigate('practice');break;case'view':navigate(v);break;case'problem':navigate(`problem/${v}`);break;case'back':navigate('practice');break;case'difficulty':difficulty=v;list();break;case'kind':kind=v;list();break;case'lab':lab=v;list();break;case'tab':tab=v;problem(activeId);break;case'guideTopic':guideIndex=Number(v);renderGuide();break;case'copyCommand':{const[i,j]=v.split(':').map(Number);copy(guide[i].cards[j].code);break;}case'copySolution':copy(p.solutionCode);break;case'fixture':download(`${p.id}-exercise.${p.kind==='Code'?'txt':'rpt'}`,p.title+'\n\n'+p.prompt+'\n\n'+p.artifact);break;case'checkNumeric':{const n=$('#numeric-answer').value;entry(v).numeric=n;save();const num=Number(n),ok=n.trim()!==''&&Number.isFinite(num)&&Math.abs(num-p.numeric.answer)<=(p.numeric.tolerance??0.001);$('#numeric-feedback').textContent=ok?'Correct value. Now explain the assumptions and what the result means.':n.trim()===''?'Enter a number first.':'Not yet. Check the units, sign, and denominator. The solution tab explains the calculation.';break;}case'done':{const en=entry(v);if(en.status==='done'){en.status='attempted';save();problem(v);break;}if(!en.notes.trim()){toast('Write your reasoning before marking this self-reviewed.');break;}if(en.checks.length<p.rubric.length){toast('Review each checklist point first.');break;}en.status='done';save();problem(v);toast('Marked self-reviewed.');break;}case'next':{const candidates=db.filter(x=>track==='All problems'||x.track===track),idx=candidates.findIndex(x=>x.id===v),next=candidates[(idx+1)%candidates.length];navigate('problem/'+next.id);break;}case'export':download('sasi-practice-progress.json',JSON.stringify({version:1,progress},null,2),'application/json');break;case'interviewTrack':interviewTrack=v;interview();break;case'interviewMinutes':interviewMinutes=Number(v);interview();break;case'startSession':startSession();break;case'resume':navigate('problem/'+session.id);break;case'finish':session.finished=true;save();tab='solution';problem(activeId);break;case'followup':session.followups=Math.min((session.followups||0)+1,p.followups.length);save();problem(activeId);break;case'scope':track='All problems';difficulty=kind='All';lab=v;search='';navigate('practice');break;}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#rows').innerHTML=listRows();$('#result-count').textContent=`${filtered().length} problems · All report fixtures are educational examples.`;}if(e.target.id==='answer'){const en=entry(e.target.dataset.id);en.notes=e.target.value;if(en.status==='new')en.status='attempted';save();$('#save-status').textContent='Saved in this browser';}if(e.target.id==='numeric-answer'){entry(activeId).numeric=e.target.value;save();}});
document.addEventListener('change',async e=>{if(e.target.hasAttribute('data-rubric')){const en=entry(e.target.dataset.id),i=Number(e.target.dataset.rubric);en.checks=e.target.checked?[...new Set([...en.checks,i])]:en.checks.filter(x=>x!==i);save();$('#score').textContent=`${en.checks.length} / ${db.find(p=>p.id===e.target.dataset.id).rubric.length} review points`;}
if(e.target.id==='import-progress'&&e.target.files[0]){try{const f=e.target.files[0];if(f.size>2000000)throw Error('Too large');const data=JSON.parse(await f.text());if(data.version!==1||typeof data.progress!=='object'||!data.progress)throw Error('Bad format');for(const p of db){const d=data.progress[p.id];if(!d)continue;const notes=typeof d.notes==='string'?d.notes.slice(0,50000):'',checks=Array.isArray(d.checks)?[...new Set(d.checks.filter(n=>Number.isInteger(n)&&n>=0&&n<p.rubric.length))]:[];progress[p.id]={notes,checks,status:d.status==='done'&&notes&&checks.length===p.rubric.length?'done':'attempted',numeric:typeof d.numeric==='string'?d.numeric.slice(0,80):''};}save();route();toast('Progress imported.');}catch{toast('Could not import. Choose a valid ASIC Practice progress export.');}}});
window.addEventListener('hashchange',route);
Promise.all(['lab-problems.json','advanced-problems.json','guide.json'].map(async f=>{const r=await fetch(f);if(!r.ok)throw Error(f);return r.json();})).then(([a,b,g])=>{db=[...a,...b];guide=g;for(const p of db)if(progress[p.id]&&!Array.isArray(progress[p.id].checks))progress[p.id].checks=[];route();}).catch(()=>{$('#app').innerHTML='<main class="loaderror"><h1>Practice content could not load.</h1><p>Reload the page. If running locally, serve this folder with an HTTP server instead of opening index.html directly.</p><button onclick="location.reload()">Reload</button></main>';});
